<?php
declare(strict_types=1);
namespace Tests;
#[\PHPUnit\Framework\Attributes\Group('database-integration')]
final class RepeatableReadTest extends TestCase
{
    public function testAuditAndMembershipUseCurrentLockedRowsRatherThanAnOldMysqlSnapshot():void
    {
        $url=getenv('ELANG_TEST_DATABASE_URL');if(!$url) self::markTestSkipped('A disposable SQL database is required.');$key=base64_encode(random_bytes(32));$one=$this->application(['key'=>$key,'database'=>['url'=>$url]]);$db=$one->container->get(\Elang\Database\Database::class)->connection();self::assertStringStartsWith('elang_test_',$db->getParams()['dbname']??'');if(!$db->getDatabasePlatform() instanceof \Doctrine\DBAL\Platforms\AbstractMySQLPlatform) self::markTestSkipped('This regression specifically exercises MySQL/MariaDB REPEATABLE READ snapshots.');\Elang\Auth\Schema::up($db);\Elang\Tenancy\Schema::up($db);$two=new \Elang\Application($this->temporary.'/other',['key'=>$key,'database'=>['url'=>$url],'paths'=>['storage'=>$this->temporary.'/other-storage']]);$suffix=bin2hex(random_bytes(4));$users=$one->container->get(\Elang\Auth\Users::class);$owner=$users->create('Owner','owner'.$suffix.'@example.test','An isolated account passphrase','user',true);$member=$users->create('Member','member'.$suffix.'@example.test','An isolated account passphrase','user',true);$teams=$one->container->get(\Elang\Tenancy\Teams::class);$team=$teams->create($owner,'Snapshot');$teams->accept($member,$teams->invite($owner,$team['id'],$member->email,'member'));$otherTeams=$two->container->get(\Elang\Tenancy\Teams::class);$db->setTransactionIsolation(\Doctrine\DBAL\TransactionIsolationLevel::REPEATABLE_READ);
        $db->beginTransaction();self::assertSame('member',$db->fetchOne('SELECT role FROM elang_members WHERE team_id = ? AND user_id = ?',[$team['id'],$member->id]));$otherTeams->role($owner,$team['id'],$member->id,'viewer');try { $teams->within($member,$team['id'],'write',fn()=>null);self::fail('A stale snapshot granted a revoked write permission.'); }catch(\Elang\Http\HttpException $e) { self::assertSame(403,$e->status); }$db->rollBack();
        $scope='team:'.$team['id'];$db->beginTransaction();$before=(int)$db->fetchOne('SELECT sequence FROM elang_audit_heads WHERE scope = ?',[$scope]);$two->container->get(\Elang\Audit\Audit::class)->append($scope,'test.second',null);$one->container->get(\Elang\Audit\Audit::class)->append($scope,'test.first',null);$db->commit();$verified=$one->container->get(\Elang\Audit\Audit::class)->verify($scope);self::assertTrue($verified['valid']);self::assertSame($before+2,$verified['sequence']);
        $db->beginTransaction();self::assertSame('viewer',$db->fetchOne('SELECT role FROM elang_members WHERE team_id = ? AND user_id = ?',[$team['id'],$member->id]));$otherTeams->remove($owner,$team['id'],$member->id);try { $teams->within($member,$team['id'],'read',fn()=>null);self::fail('A stale snapshot retained removed membership.'); }catch(\Elang\Http\HttpException $e) { self::assertSame(404,$e->status); }$db->rollBack();
    }
}
